'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );


// FIXTURES //

var fixtures = require( './fixtures/cpp/output.json' );
var lowerRegularized = fixtures.lower_regularized;
var lowerUnregularized = fixtures.lower_unregularized;
var upperRegularized = fixtures.upper_regularized;
var upperUnregularized = fixtures.upper_unregularized;
var x = fixtures.x;
var a = fixtures.a;
var b = fixtures.b;


// VARIABLES //

var betainc = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( betainc instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof betainc, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if `x` is outside `[0,1]`', opts, function test( t ) {
	var val = betainc( -0.2, 1.0, 1.0 );
	t.equal( isnan( val ), true, 'returns NaN' );

	val = betainc( 1.1, 1.0, 1.0 );
	t.equal( isnan( val ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `NaN` negative `a` or `b`', opts, function test( t ) {
	var val = betainc( 0.5, -1.0, 1.0 );
	t.equal( isnan( val ), true, 'returns NaN' );

	val = betainc( 0.5, 1.0, -1.0 );
	t.equal( isnan( val ), true, 'returns NaN' );

	val = betainc( 0.5, -1.0, -1.0 );
	t.equal( isnan( val ), true, 'returns NaN' );
	t.end();
});

tape( 'the function evaluates the lower regularized incomplete beta function', opts, function test( t ) {
	var expected;
	var i;
	var y;

	expected = lowerRegularized;
	for ( i = 0; i < x.length; i++ ) {
		y = betainc( x[i], a[i], b[i] );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 90 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the lower unregularized incomplete beta function', opts, function test( t ) {
	var expected;
	var i;
	var y;

	expected = lowerUnregularized;
	for ( i = 0; i < x.length; i++ ) {
		y = betainc( x[i], a[i], b[i], false );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 100 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the upper regularized incomplete beta function', opts, function test( t ) {
	var expected;
	var i;
	var y;

	expected = upperRegularized;
	for ( i = 0; i < x.length; i++ ) {
		y = betainc( x[i], a[i], b[i], true, true );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 100 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the upper unregularized incomplete beta function', opts, function test( t ) {
	var expected;
	var i;
	var y;

	expected = upperUnregularized;
	for ( i = 0; i < x.length; i++ ) {
		y = betainc( x[i], a[i], b[i], false, true );
		t.strictEqual( isAlmostSameValue( y, expected[ i ], 120 ), true, 'returns expected value' );
	}
	t.end();
});
